SELECT COUNT(*)
FROM conversations
WHERE shop_id = #{shopId}
  AND created_at >= #{from}
  AND created_at < #{to}
  AND turn_count > 0

SELECT COUNT(DISTINCT e.conversation_id)
FROM escalations e
JOIN conversations c ON e.conversation_id = c.id
WHERE e.shop_id = #{shopId}
  AND c.created_at >= #{from}
  AND c.created_at < #{to}

